  /** @nullable */
  screenName?: string | null;
  startsAt?: string;
  endsAt?: string;
  /** The source system's status flag. O = open (the only bookable one), C = closed, I = inactive. */
  status?: string;
  /** @nullable */
  cinemaName?: string | null;
  /** @nullable */
